import React, { useState } from 'react';
import { Modal, Button } from 'react-bootstrap';

function CalculadorGastos() {
  const [participantes, setParticipantes] = useState([{ nombre: '', monto: '' }]);
  const [promedio, setPromedio] = useState(0);
  const [totalMonto, setTotalMonto] = useState(0);
  const [resultado, setResultado] = useState([]);
  const [showAlert, setShowAlert] = useState(false);
  const [mostrarResultados, setMostrarResultados] = useState(false);
  const [errorNombreRepetido, setErrorNombreRepetido] = useState(false);
  const [errorMontoNegativo, setErrorMontoNegativo] = useState(false);
 

  // Agregar un nuevo participante
  const handleAddParticipante = () => {
    // Verificar si el último participante tiene un nombre vacío
    const ultimoParticipante = participantes[participantes.length - 1];
    if (ultimoParticipante.nombre.trim() === '') {
      setShowAlert(true); // Mostrar error si el último participante tiene un nombre vacío
      return; // No agregar un nuevo participante
    }
  
    // Agregar un nuevo participante si el último tiene un nombre válido
    setParticipantes([...participantes, { nombre: '', monto: '' }]);
  };

  // Cambiar el nombre de un participante
  const handleCambiarNombre = (index, newNombre) => {
    // Actualizar el nombre en tiempo real
    const actualizacionParticipantes = [...participantes];
    actualizacionParticipantes[index].nombre = newNombre;
    setParticipantes(actualizacionParticipantes);
  };

  const handleValidarNombre = (index, newNombre) => {
    // Validar si el nombre está vacío
    if (newNombre.trim() === '') {
      setShowAlert(true); 
      return false; 
    }
  
    // Validar si el nombre ya existe
    const nombreRepetido = participantes.some(
      (participante, i) =>
        i !== index && participante.nombre.toLowerCase() === newNombre.toLowerCase()
    );
  
    if (nombreRepetido) {
      setErrorNombreRepetido(true); 
      return false; 
    }
    setShowAlert(false);
    setErrorNombreRepetido(false);
    return true; 
  };

  const handleEliminarParticipante = (index) => {
    if (participantes.length > 1) {
      const actualizacionParticipantes = [...participantes];
      actualizacionParticipantes.splice(index, 1);
      setParticipantes(actualizacionParticipantes);
    }
    if (participantes.length === 1) {
      setParticipantes([{ nombre: '', monto: '' }]);
    }
  };

  const handleCambiarMonto = (index, newMonto) => {
    const actualizacionParticipantes = [...participantes];
    actualizacionParticipantes[index].monto = newMonto;
    setParticipantes(actualizacionParticipantes);
  };

  const handleCambiarMontoValidado = (index, value) => {
    // Permitir expresiones matemáticas
    const regex = /^[0-9+\-*/.()\s]*$/; // Expresión regular para números, operadores y paréntesis
    if (regex.test(value)) {
      // Validar si el valor es un número negativo
      if (value.startsWith('-')) {
        setErrorMontoNegativo(true); // Mostrar error si el número es negativo
        return;
      }
      handleCambiarMonto(index, value);
    }
  };

  const calcularResultadoExpresion = (expresion) => {
    try {
      // Calcular el resultado de la expresión
      const resultado = eval(expresion);
      if (isNaN(resultado) || resultado < 0) {
        return ''; // Devolver vacío si no es un número válido o es menor a 0
      }
      return resultado;
    } catch (error) {
      return ''; // Devolver vacío si hay un error en la expresión
    }
  };

  const handleBlurMonto = (index) => {
    const participante = participantes[index];
    if (participante.monto) {
      const resultadoCalculado = calcularResultadoExpresion(participante.monto);
      if (resultadoCalculado !== '' && !isNaN(resultadoCalculado)) { // Verificar que sea un número válido
        if (resultadoCalculado < 0) {
          setErrorMontoNegativo(true); // Mostrar error si el resultado es menor a 0
        } else {
          setErrorMontoNegativo(false); // Limpiar el error si el resultado es válido
          handleCambiarMonto(index, resultadoCalculado.toString()); // Convertir a string solo si es válido
        }
      } else {
        setErrorMontoNegativo(true); // Mostrar error si la expresión no es válida
      }
    }
  };

  const handleCalculate = () => {
    // Evaluar los montos antes de calcular
    const participantesActualizados = participantes.map((participante) => {
      const montoCalculado = calcularResultadoExpresion(participante.monto);
      return {
        ...participante,
        monto: montoCalculado !== '' ? montoCalculado.toString() : participante.monto, // Actualizar el monto si es válido
      };
    });

    const nombresValidos = participantesActualizados.every(
      (participante, index) => handleValidarNombre(index, participante.nombre)
    );
  
    if (!nombresValidos) {
      return; // Detener el cálculo si hay nombres vacíos o repetidos
    }

    // Filtrar participantes con nombre o monto válido
    const participantesFiltrados = participantesActualizados.filter(
      (participante) => participante.nombre !== '' || participante.monto !== ''
    );

    // // Verificar si hay participantes sin nombre pero con monto
    // const participanteSinNombre = participantesFiltrados.find(
    //   (participante) => participante.nombre === '' && participante.monto !== ''
    // );
    // if (participanteSinNombre) {
    //   setShowAlert(true);
    //   return;
    // }

    // Calcular el total
    const total = participantesFiltrados.reduce(
      (acum, participante) => acum + parseFloat(participante.monto || 0),
      0
    );
    setTotalMonto(total);

    // Calcular el promedio
    const montoPromedio =
      participantesFiltrados.length > 0 ? total / participantesFiltrados.length : 0;
    setPromedio(montoPromedio);

    // Calcular quién debe pagar a quién
    const pagos = participantesFiltrados.map((participante) => ({
      nombre: participante.nombre,
      debe: parseFloat(participante.monto || 0) - montoPromedio,
    }));

    const deudores = pagos.filter((amigo) => amigo.debe <= 0);
    const recibenDinero = pagos.filter((amigo) => amigo.debe > 0);

    deudores.sort((a, b) => a.debe - b.debe);
    recibenDinero.sort((a, b) => b.debe - a.debe);

    const transacciones = [];

    deudores.forEach((deudor) => {
      recibenDinero.forEach((acreedor) => {
        const montoTransferir = Math.min(Math.abs(deudor.debe), acreedor.debe);
        if (montoTransferir > 0) {
          transacciones.push({
            deudor: deudor.nombre,
            acreedor: acreedor.nombre,
            cantidad: montoTransferir,
          });
          deudor.debe += montoTransferir;
          acreedor.debe -= montoTransferir;
        }
      });
    });

    setResultado(transacciones);
    setMostrarResultados(true);
  };

  const handleLimpiar = () => {
    setParticipantes([{ nombre: '', monto: '' }]);
    setPromedio(0);
    setTotalMonto(0);
    setResultado([]);
    setMostrarResultados(false);
  };

  return (
    <div className="container-fluid px-0">
      <div className="row justify-content-center">
        <div className="col-md-8">
          <Modal show={errorNombreRepetido} onHide={() => setErrorNombreRepetido(false)}>
            <Modal.Header closeButton>
              <Modal.Title>ERROR</Modal.Title>
            </Modal.Header>
            <Modal.Body>
              ¡El nombre ya existe! Ponele un apodito ;)
            </Modal.Body>
            <Modal.Footer>
              <Button variant="secondary" onClick={() => setErrorNombreRepetido(false)}>
                Cerrar
              </Button>
            </Modal.Footer>
          </Modal>
          <Modal show={showAlert} onHide={() => setShowAlert(false)}>
            <Modal.Header closeButton>
              <Modal.Title>Error</Modal.Title>
            </Modal.Header>
            <Modal.Body>
              Por favor, ingrese un nombre para todos los participantes.
            </Modal.Body>
            <Modal.Footer>
              <Button variant="secondary" onClick={() => setShowAlert(false)}>
                Cerrar
              </Button>
            </Modal.Footer>
          </Modal>
          <Modal show={errorMontoNegativo} onHide={() => setErrorMontoNegativo(false)}>
            <Modal.Header closeButton>
              <Modal.Title>Error</Modal.Title>
            </Modal.Header>
            <Modal.Body>
              El monto no puede ser menor a 0. Por favor, ingrese un valor válido.
            </Modal.Body>
            <Modal.Footer>
              <Button variant="secondary" onClick={() => setErrorMontoNegativo(false)}>
                Cerrar
              </Button>
            </Modal.Footer>
          </Modal>

          {participantes.map((participante, index) => (
            <div key={index} className="d-flex justify-content-center my-2">
              <div className="form-group row align-items-center mx-2">
                <div className="col" style={{ paddingLeft: "30px", paddingRight: "4px" }}>
                  <label>
                    {index === 0 && <label>Nombre</label>}
                    <input
                      type="text"
                      className="form-control col-12 col-md-6"
                      placeholder="Nombre"
                      value={participante.nombre}
                      onChange={(e) => handleCambiarNombre(index, e.target.value)}
                      onBlur={(e) => handleValidarNombre(index, e.target.value)}
                    />
                  </label>
                </div>
                <div className="col px-0 d-flex justify-content-center">
                  <label>
                    {index === 0 && <label className="ml-2">Monto</label>}
                    <input
                      type="text"
                      className="form-control col-12 col-md-6   form-control"
                      style={{ marginLeft: '4px' }}
                      placeholder="Acá podes sumar"
                      value={participante.monto}
                      onChange={(e) => handleCambiarMontoValidado(index, e.target.value)}
                      onBlur={() => handleBlurMonto(index)} // Calcular al salir del campo
                    // inputMode="decimal"
                    // pattern="[-+]?[0-9]*[.,]?[0-9]*"
                    />
                  </label>
                </div>
                <div className="col-1 d-flex justify-content px-0 ">
                  <button
                    className="btn btn-danger btn-sm"
                    style={{
                      width: '30px',
                      height: '25px',
                      alignItems: 'center',
                      display: 'flex',
                      justifyContent: 'center',
                      color: 'grey',
                      lineHeight: '1',
                      border: 'none',
                      fontWeight: 'bold',
                      backgroundColor: 'transparent',
                    }}
                    onClick={() => handleEliminarParticipante(index)}
                  >
                    ×
                  </button>
                </div>
              </div>
              <br />
            </div>
          ))}

          <div className="d-flex justify-content-center mb-3">
            <button className="btn btn-primary mx-1" onClick={handleAddParticipante}>Agregar</button>
            <button className="btn btn-primary mx-1" onClick={handleLimpiar}>Limpiar</button>
          </div>

          <div className="d-flex justify-content-center">
            <button className="btn btn-success" onClick={handleCalculate}>Calcular</button>
          </div>

          {mostrarResultados && (
            <p className="d-flex justify-content-center my-4">
              Gasto total: ${totalMonto.toFixed(2)}
              <br />
              Cada uno: ${promedio.toFixed(2)}
            </p>
          )}

          {resultado.length > 0 && (
            <div className='d-flex flex-column align-items-center'>
              <p style={{ fontSize: '20px', fontWeight: 'bold' }}>DETALLES DE PAGO</p>
              <ul style={{ paddingLeft: '15px' }}>
                {resultado.map((transaccion, index) => (
                  <li key={index}>
                    {transaccion.deudor.charAt(0).toUpperCase() + transaccion.deudor.slice(1).toLowerCase()} debe pagar ${Math.abs(transaccion.cantidad).toFixed(2)} a {transaccion.acreedor.charAt(0).toUpperCase() + transaccion.acreedor.slice(1).toLowerCase()}
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default CalculadorGastos;